wedAt":{"path":"nodes.load_page.output.lastReviewedAt","type":"field"},"now":{"path":"now","type":"field"},"publishedAt":{"path":"nodes.load_page.output.publishedAt","type":"field"},"title":{"path":"nodes.load_page.output.title","type":"field"}},"type":"object"},"type":"llm"},{"capabilities":{"actions":[{"actionType":"knowledge.page.mark_reviewed","resourceType":"knowledge_space"},{"actionType":"knowledge.page.archive","resourceType":"knowledge_space"}],"maxEffects":2},"id":"review_page","input":{"fields":{"llmText":{"path":"nodes.analyze.output.text","type":"field"},"page":{"path":"nodes.load_page.output","type":"field"},"pageId":{"path":"loop.item.pageId","type":"field"},"spaceId":{"path":"workflow.input.spaceId","type":"field"}},"type":"object"},"label":"Review page","program":{"programId":"prog:knowledge-review-page","sourceDigest":"sha256:9d3a4d822128de90e7b109e1eaf1620f296b30e60f2f2756a8510639760bfde5","version":2},"type":"program"},{"id":"page_result","type":"output","value":{"path":"nodes.review_page.output","type":"field"}}]},"collection":{"path":"nodes.list_stale.output.pages","type":"field"},"concurrency":4,"id":"review","label":"Review pages","maxItems":50,"type":"for_each"},{"id":"end","type":"output","value":{"fields":{"pages":{"path":"nodes.review.output","type":"field"},"spaceId":{"path":"workflow.input.spaceId","type":"field"}},"type":"object"}}]},"id":"wf:knowledge-maintain-space","inputFields":[{"label":"Space","path":"workflow.input.spaceId","type":"string"}],"name":"Knowledge: maintain space"},"definitionId":"wf:knowledge-maintain-space","publishedAt":"2026-09-30T00:00:00.000Z","publishedBy":{"id":"service:catalog-knowledge","type":"service"},"version":2}', '2026-09-30T00:00:00.000Z');
